let dadosRecebidosDaAPI;
if ($input.item && typeof $input.item.json !== 'undefined') {
    dadosRecebidosDaAPI = $input.item.json;
} else if ($items && $items.length > 0 && typeof $items[0].json !== 'undefined') {
    dadosRecebidosDaAPI = $items[0].json;
} else {
    console.error("Nenhum dado JSON de entrada encontrado ou formato inesperado.");
    return [{ json: { erro: "Dados de entrada não encontrados ou em formato incorreto." } }];
}

let objetoPrincipal;
if (Array.isArray(dadosRecebidosDaAPI) && dadosRecebidosDaAPI.length > 0) {
    objetoPrincipal = dadosRecebidosDaAPI[0];
} else if (typeof dadosRecebidosDaAPI === 'object' && dadosRecebidosDaAPI !== null && dadosRecebidosDaAPI.hasOwnProperty('itensTabelaPreco')) {
    objetoPrincipal = dadosRecebidosDaAPI;
} else {
    console.error("Estrutura do JSON da API não reconhecida ou chave 'itensTabelaPreco' não encontrada no objeto principal.");
    return [{ json: { erro: "Estrutura do JSON da API não reconhecida ou 'itensTabelaPreco' ausente." } }];
}

if (!objetoPrincipal || typeof objetoPrincipal.itensTabelaPreco === 'undefined' || !Array.isArray(objetoPrincipal.itensTabelaPreco)) {
    console.error("'itensTabelaPreco' não é um array válido ou não foi encontrado.");
    return [{ json: { erro: "'itensTabelaPreco' não encontrado ou não é um array." } }];
}

const listaDeProdutosOriginal = objetoPrincipal.itensTabelaPreco;

const listaDeProdutosFinal = listaDeProdutosOriginal.map(produto => {
    let precoTratado = null;
    if (produto.preco && typeof produto.preco === 'string') {
        const precoLimpo = produto.preco.replace(/\./g, '').replace(',', '.');
        const valorNumerico = parseFloat(precoLimpo);
        if (!isNaN(valorNumerico)) {
            precoTratado = valorNumerico;
        } else {
            console.warn(`Preço inválido "${produto.preco}" para produto ID: ${produto.idProduto || 'N/A'}`);
        }
    } else if (typeof produto.preco === 'number') {
        precoTratado = produto.preco;
    }

    return {
        descricaoProduto: produto.descricaoProduto || "Sem descrição",
        idProduto: produto.idProduto || null,
        nomeProduto: produto.nomeProduto || "Sem nome",
        preco: precoTratado,
        siglaUnidadeMedidaProduto: produto.siglaUnidadeMedidaProduto || "UN",
        ativo: objetoPrincipal.ativo, 
        idTabela: objetoPrincipal.id  
    };
});

return listaDeProdutosFinal;

// Pega todos os itens que vieram do Merge
const pedidosPagina = $input.all();

// Funcao auxiliar para converter data DD/MM/YYYY HH:mm:ss para ISO
function parseDataNomus(dataStr) {
  if (!dataStr) return null;
  const [data, hora] = dataStr.split(' ');
  if (!data) return null;
  const [dia, mes, ano] = data.split('/');
  if (!dia || !mes || !ano) return null;
  return hora ? `${ano}-${mes}-${dia}T${hora}` : `${ano}-${mes}-${dia}T00:00:00`;
}

// Processa item por item
const pedidosTratados = pedidosPagina.map(item => {
  const json = item.json;

  // 1. Tratamento do valor monetario
  let valorTratado = 0;
  if (json.valorTotal) {
    valorTratado = Number(String(json.valorTotal).replace(/\./g,'').replace(',', '.'));
  }

  // 2. Data de criacao
  const dataTratada = parseDataNomus(json.dataCriacao);

  // 3. Status baseado em observacoes
  const obs = json.observacoesInternas;
  const temProblema = obs && obs.trim() !== "";
  const observacaoFinal = temProblema ? obs : null;
  const statusPedido = temProblema ? "COM_PROBLEMA" : "RESOLVIDO";

  // 4. NOVOS CAMPOS — vendedor, cliente, prazo, NFes
  const idVendedor = json.idPessoaVendedor || null;
  const idCliente = json.idPessoaCliente || null;
  const dataEntregaPadrao = parseDataNomus(json.dataEntregaPadrao);

  // NFes e data de faturamento (pega a NFe mais recente)
  const nfes = json.nfes || [];
  let dataFaturamento = null;
  if (nfes.length > 0) {
    const datasNfe = nfes
      .filter(n => n.dataProcessamento)
      .map(n => parseDataNomus(n.dataProcessamento))
      .filter(Boolean)
      .sort();
    if (datasNfe.length > 0) {
      dataFaturamento = datasNfe[datasNfe.length - 1];
    }
  }

  // Parcelas
  const parcelas = json.parcelas || [];

  // 5. Calculo de entrega no prazo
  let entregueNoPrazo = null;
  if (nfes.length > 0 && json.dataEntregaPadrao) {
    const [diaE, mesE, anoE] = json.dataEntregaPadrao.split(' ')[0].split('/');
    const prazo = new Date(`${anoE}-${mesE}-${diaE}`);
    const datasNfe = nfes
      .filter(n => n.dataProcessamento)
      .map(n => {
        const [d, m, a] = n.dataProcessamento.split('/');
        return new Date(`${a}-${m}-${d}`);
      })
      .sort((a, b) => b - a);
    if (datasNfe.length > 0) {
      entregueNoPrazo = datasNfe[0] <= prazo;
    }
  }

  // 6. Dias de atraso
  let diasAtraso = 0;
  if (json.dataEntregaPadrao) {
    const [diaE, mesE, anoE] = json.dataEntregaPadrao.split(' ')[0].split('/');
    const prazo = new Date(`${anoE}-${mesE}-${diaE}`);
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);

    if (nfes.length > 0) {
      const datasNfe = nfes
        .filter(n => n.dataProcessamento)
        .map(n => {
          const [d, m, a] = n.dataProcessamento.split('/');
          return new Date(`${a}-${m}-${d}`);
        })
        .sort((a, b) => b - a);
      if (datasNfe.length > 0 && datasNfe[0] > prazo) {
        diasAtraso = Math.ceil((datasNfe[0] - prazo) / (1000 * 60 * 60 * 24));
      }
    } else if (hoje > prazo) {
      diasAtraso = Math.ceil((hoje - prazo) / (1000 * 60 * 60 * 24));
    }
  }

  return {
    json: {
      codigo_pedido: json.codigoPedido,
      id_tipo_pedido: json.idTipoPedido,
      valor_total: valorTratado,
      observacoes_internas: observacaoFinal,
      data_criacao: dataTratada,
      itens_pedido: { data: json.itensPedido },
      status_monitoramento: statusPedido,
      id_vendedor: idVendedor,
      id_cliente: idCliente,
      data_entrega_padrao: dataEntregaPadrao,
      data_faturamento: dataFaturamento,
      nfes_json: JSON.stringify(nfes),
      parcelas_json: JSON.stringify(parcelas),
      entregue_no_prazo: entregueNoPrazo,
      dias_atraso: diasAtraso
    }
  };
});

return pedidosTratados;

const fontes = $('Buscar Delta Specs').all();
const respostas = $input.all();
const saida = [];

const semAcento = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const mapaUnidades = { litro: 'l', litros: 'l', lt: 'l', tonelada: 'tf', toneladas: 'tf', ton: 'tf', t: 'tf', tf: 'tf', polegada: 'pol', polegadas: 'pol' };

for (let i = 0; i < respostas.length; i++) {
  const item = respostas[i];
  const pareado = Array.isArray(item.pairedItem) ? item.pairedItem[0]?.item : item.pairedItem?.item;
  const fonte = fontes[Number.isInteger(pareado) ? pareado : i]?.json ?? fontes[i]?.json;
  if (!fonte?.codigo_produto || !fonte?.descricao_produto) continue;

  let bruto = item.json?.text ?? item.json?.output ?? item.json?.response ?? '';
  if (typeof bruto === 'object' && bruto !== null) bruto = JSON.stringify(bruto);
  bruto = String(bruto).trim();
  const cerca = String.fromCharCode(96).repeat(3);
  if (bruto.startsWith(cerca)) bruto = bruto.slice(3).replace(/^json\s*/i, '');
  if (bruto.endsWith(cerca)) bruto = bruto.slice(0, -3);
  bruto = bruto.trim();

  let spec;
  try { spec = JSON.parse(bruto); } catch { continue; }

  let tipo = semAcento(spec.tipo);
  if (tipo.includes('prensa')) tipo = 'prensa';
  else if (tipo.includes('agitador')) tipo = 'agitador';
  else if (tipo.includes('alavanca')) tipo = 'alavanca';
  else if (tipo.includes('concha')) tipo = 'concha';
  else if (tipo.includes('luva')) tipo = 'luva';
  if (!tipo || tipo.length > 60) continue;

  let medida = spec.medida === null || spec.medida === undefined || spec.medida === '' ? null : Number(spec.medida);
  if (medida !== null && !Number.isFinite(medida)) medida = null;

  let unidade = spec.unidade == null ? null : semAcento(spec.unidade);
  unidade = mapaUnidades[unidade] ?? unidade;
  const permitidas = new Set(['mm','cm','m','ml','l','kg','g','lb','pol','tf','kgf','un']);
  if (unidade && !permitidas.has(unidade)) unidade = null;

  const descricaoNumerica = semAcento(fonte.descricao_produto).replace(',', '.');
  if (medida !== null) {
    const representacoes = [String(medida), String(medida).replace('.', ',')];
    if (!representacoes.some(v => descricaoNumerica.includes(v.replace(',', '.')))) {
      medida = null;
      unidade = null;
    }
  }

  const detalhes = spec.detalhes && typeof spec.detalhes === 'object' && !Array.isArray(spec.detalhes) ? spec.detalhes : {};
  saida.push({ json: {
    codigoProduto: String(fonte.codigo_produto),
    tipo,
    medida,
    unidade,
    material: spec.material == null ? null : String(spec.material).trim() || null,
    detalhes
  }});
}

return saida;

